def construct_min_palindrome(non_palindrome):

    # if string is already a palindrome
    if non_palindrome == non_palindrome[::-1]:
        return non_palindrome

    # iterate over all characters in the string
    for i in range(len(non_palindrome)):

        # if two characters at symmetric position are not equal
        if non_palindrome[i] != non_palindrome[len(non_palindrome) - i - 1]:

            # insert the larger character at beginning of the string
            if non_palindrome[i] > non_palindrome[len(non_palindrome) - i - 1]:
                non_palindrome = non_palindrome[:] + non_palindrome[i]

            # otherwise, at the end of the string
            else:
                non_palindrome = non_palindrome[i] + non_palindrome[:]

            # check if the resulting string is a palindrome
            if non_palindrome == non_palindrome[::-1]:
                return non_palindrome

    # if after trying all possible insertions, no palindrome is found, return an empty string    
    return ""

