def binary_search(arr, low, high, target):

    if low > high:
        return -1

    mid = (low + high) // 2

    if arr[mid] == target:
        return mid

    if arr[low] <= arr[mid]:
        if arr[low] <= target <= arr[mid]:
            return binary_search(arr, low, mid - 1, target)
        return binary_search(arr, mid + 1, high, target)

    if arr[mid] <= target <= arr[high]:
        return binary_search(arr, mid + 1, high, target)
    return binary_search(arr, low, mid - 1, target)

